    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            for j in range(i+1, m):
                factor = A[j][i] / A[i][i]
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
        return A

    def matrix_mult(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0]*p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def matrix_det(A):
        m, n = len(A), len(A[0])
        if m != n:
            raise ValueError("Matrix must be square")
        det = 1
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            det *= A[i][i]
            if det == 0:
                return 0
            for j in range(i+1, m):
                factor = A[j][i] / A[i][i]
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
        return det

    def generate_boolean_circuit(w: int):
        n = 2**w
        circuit = []
        for i in range(1, n):
            if random.choice([True, False]):
                gate = (random.choice(['AND', 'OR']), [i-1, i])
            else:
                gate = ('NOT', [i-1])
            circuit.append(gate)
        return circuit

    def tseitin_formula(circuit):
        n = 2**len(circuit)
        formula = []
        for i in range(n):
            clause = []
            for j in range(len(circuit)):
                if circuit[j][0] == 'NOT':
                    if (i >> j) & 1:
                        clause.append(-(circuit[j][1][0] + 1))
                    else:
                        clause.append(circuit[j][1][0])
                elif circuit[j][0] == 'AND':
                    if (i >> j) & 1:
                        clause.append(circuit[j][1][0])
                        clause.append(circuit[j][1][1])
                    else:
                        clause.append(-(circuit[j][1][0] + 1))
                        clause.append(-(circuit[j][1][1] + 1))
                elif circuit[j][0] == 'OR':
                    if (i >> j) & 1:
                        clause.append(circuit[j][1][0])
                        clause.append(circuit[j][1][1])
                    else:
                        clause.append(-(circuit[j][1][0] + 1))
            formula.append(clause)
        return formula

    def affine_quasi_projective_variety(formula):
        n = len(formula)
        A = [[0]*n for _ in range(n)]
        b = [0]*n
        for i in range(n):
            for j in range(i, n):
