                else:
                    A[i][j] = -1
            b[i] = formula[i].count(0)
        A = gaussian_elimination(A)
        det = matrix_det(A)
        return abs(det)

    def monotone_width(circuit):
        width = 0
        for gate in circuit:
            if gate[0] == 'NOT':
                width += 1
            elif gate[0] == 'AND' or gate[0] == 'OR':
                width = max(width, len(gate[1]))
        return width

